170		if _, err := src.registerAsset("EQ-A", "打印机", "一楼"); err != nil {
171			t.Fatal(err)
172		}
173		if _, _, err := src.report("EQ-A", "卡纸", "req-a1"); err != nil { // T0001
174			t.Fatal(err)
175		}
176		if _, err := src.withdrawPart("T0001", "FILTER-01", 4, "更换滤芯"); err != nil { // P0001
177			t.Fatal(err)
178		}
179		if _, _, err := src.returnPart("P0001", 1, "多余"); err != nil {
180			t.Fatal(err)
181		}
182		if _, _, err := src.closeTicket("T0001", "已修复"); err != nil {
183			t.Fatal(err)
184		}
185		if _, _, err := src.report("EQ-A", "无法开机", "req-a2"); err != nil { // T0002
186			t.Fatal(err)
187		}
188		if _, err := src.withdrawPart("T0002", "ROLLER-02", 2, "更换搓纸轮"); err != nil { // P0002
189			t.Fatal(err)
190		}
191		mustSave(t, src)
192	
193		// 目标：EQ-X 一张未关闭工单，已有一笔领用 P0001。
194		dst := newStoreAt(t, dstDir)
195		if _, err := dst.registerAsset("EQ-X", "叉车", "仓库"); err != nil {
196			t.Fatal(err)
197		}
198		if _, _, err := dst.report("EQ-X", "抖动", "req-x1"); err != nil { // T0001
199			t.Fatal(err)
200		}
201		if _, err := dst.withdrawPart("T0001", "BELT-01", 1, "更换皮带"); err != nil { // P0001
202			t.Fatal(err)
203		}
204		mustSave(t, dst)
205	
206		srcBefore := readFileBytes(t, srcDir)
207		dstBefore := readFileBytes(t, dstDir)
208	
209		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-A"})
210		if err != nil {
211			t.Fatalf("导入失败: %v", err)
212		}
213		wantParts := []partRemap{{"P0001", "P0002"}, {"P0002", "P0003"}}
214		if len(outcome.parts) != len(wantParts) {
215			t.Fatalf("领用映射数 = %d, 想得到 %d", len(outcome.parts), len(wantParts))
216		}
217		for i, m := range outcome.parts {
218			if m != wantParts[i] {
219				t.Fatalf("领用映射[%d] = %v, 想得到 %v", i, m, wantParts[i])
220			}
221		}
222		if string(readFileBytes(t, srcDir)) != string(srcBefore) {
223			t.Fatal("导入不应修改源台账")
224		}
225		if string(dstBefore) == string(readFileBytes(t, dstDir)) {
226			t.Fatal("目标台账应已更新")
227		}
228	
229		s, err := openStore(dstDir)
230		if err != nil {
231			t.Fatalf("重载目标: %v", err)
232		}
233		if s.data.NextPartSeq != 4 {
234			t.Fatalf("下一领用序号 = %d, 想得到 4", s.data.NextPartSeq)
235		}
236		// 目标原有记录不变。
237		orig := s.findPart("P0001")
238		if orig == nil || orig.TicketID != "T0001" || orig.PartID != "BELT-01" || orig.Quantity != 1 {
239			t.Fatalf("目标原有领用 P0001 不应改变，得到 %+v", orig)
240		}
241		// 导入记录：工单引用同步替换，数量与累计退回保持。
242		p2 := s.findPart("P0002")
243		if p2 == nil || p2.TicketID != "T0002" || p2.AssetID != "EQ-A" ||
244			p2.Quantity != 4 || p2.Returned != 1 || p2.Note != "更换滤芯" {
245			t.Fatalf("导入的 P0002 业务信息应保留，得到 %+v", p2)
246		}
247		// 退回履历的领用引用同步更新。
248		var retEv *Event
249		for i := range s.data.Events {
250			if s.data.Events[i].Kind == eventPartReturn {
251				retEv = &s.data.Events[i]
252			}
253		}
254		if retEv == nil || retEv.WithdrawalID != "P0002" || retEv.TicketID != "T0002" || retEv.Quantity != 1 {
255			t.Fatalf("退回履历引用应同步更新，得到 %+v", retEv)
256		}
257		// 导入的未关闭工单（映射后 T0003）可继续退回。
258		got, _, err := s.returnPart("P0003", 1, "多余退回")
259		if err != nil {
260			t.Fatalf("导入的未关闭工单应可继续退回: %v", err)
261		}
262		if got.Returned != 1 || got.Quantity-got.Returned != 1 {
263			t.Fatalf("退回后累计应为 1、净量 1，得到 %+v", got)
264		}
265		mustSave(t, s)
266		if _, err := openStore(dstDir); err != nil {
267			t.Fatalf("退回后的台账应保持一致: %v", err)
268		}
269	}
270	
271	// 矛盾：退回指向未知或更晚的领用、累计退回超原数量、终结后出现领用/退回履历、
272	// 领用编号重复等，加载即拒绝并保留原文件字节，不自动修复。
273	func TestPartContradictoryLedgerRejected(t *testing.T) {
274		// 合法基准：T0001 未关闭，P0001 领用 2，一条退回 1。
275		base := `{
276	  "version": 1,
277	  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"维修中"}],
278	  "tickets": [{"id":"T0001","asset_id":"EQ-1","description":"卡纸","request_id":"req-1","status":"未关闭","created_at":"2026-10-01T08:00:00Z"}],
279	  "events": [
280	    {"seq":1,"asset_id":"EQ-1","ticket_id":"T0001","kind":"报修","content":"卡纸","time":"2026-10-01T08:00:00Z"},
281	    {"seq":2,"asset_id":"EQ-1","ticket_id":"T0001","kind":"领用","content":"更换滤芯","part_id":"FILTER-01","quantity":2,"withdrawal_id":"P0001","time":"2026-10-01T09:00:00Z"},
282	    {"seq":3,"asset_id":"EQ-1","ticket_id":"T0001","kind":"退回","content":"多余","part_id":"FILTER-01","quantity":1,"withdrawal_id":"P0001","time":"2026-10-01T10:00:00Z"}
283	  ],
284	  "requests": [{"request_id":"req-1","asset_id":"EQ-1","description":"卡纸","ticket_id":"T0001"}],
285	  "parts": [{"id":"P0001","ticket_id":"T0001","asset_id":"EQ-1","part_id":"FILTER-01","quantity":2,"note":"更换滤芯","returned":1}],
286	  "next_ticket_seq": 2,
287	  "next_part_seq": 2
288	}`
289		write := func(t *testing.T, mutate func(m map[string]any)) (string, []byte) {
290			t.Helper()
291			var m map[string]any
292			if err := json.Unmarshal([]byte(base), &m); err != nil {
293				t.Fatal(err)
294			}
295			mutate(m)
296			raw, err := json.Marshal(m)
297			if err != nil {
298				t.Fatal(err)
299			}
300			dir := t.TempDir()
301			if err := os.WriteFile(filepath.Join(dir, dataFileName), raw, 0o644); err != nil {
302				t.Fatal(err)
303			}
304			return dir, raw
305		}
306		eventsOf := func(m map[string]any) []any { return m["events"].([]any) }
307	
308		cases := []struct {
309			name   string
310			mutate func(m map[string]any)
311		}{
312			{"退回指向未知领用编号", func(m map[string]any) {
313				eventsOf(m)[2].(map[string]any)["withdrawal_id"] = "P0009"
314			}},
315			{"累计退回超过原数量", func(m map[string]any) {
316				eventsOf(m)[2].(map[string]any)["quantity"] = 2 // 累计 2+? -> 退回 2 > 剩余 1
317			}},
318			{"保存的累计退回与履历不符", func(m map[string]any) {
319				m["parts"].([]any)[0].(map[string]any)["returned"] = 0
320			}},
321			{"领用记录缺少领用履历", func(m map[string]any) {
322				m["events"] = eventsOf(m)[:2]
323				m["parts"].([]any)[0].(map[string]any)["returned"] = 0
324				// 再加一笔没有履历的领用记录。
325				m["parts"] = append(m["parts"].([]any), map[string]any{
326					"id": "P0002", "ticket_id": "T0001", "asset_id": "EQ-1",
327					"part_id": "ROLLER-02", "quantity": 1, "note": "搓纸轮", "returned": 0,
328				})
329				m["next_part_seq"] = 3
330			}},
331			{"终结后出现退回履历", func(m map[string]any) {
332				tk := m["tickets"].([]any)[0].(map[string]any)
333				tk["status"] = "已关闭"
334				tk["result"] = "已修复"
335				tk["closed_at"] = "2026-10-01T09:30:00Z"
336				m["assets"].([]any)[0].(map[string]any)["status"] = "可用"
337				ev := eventsOf(m)
338				// 在领用之后、退回之前插入关闭履历，退回仍在终结之后。
339				closeEv := map[string]any{
340					"seq": 4, "asset_id": "EQ-1", "ticket_id": "T0001", "kind": "关闭",
341					"content": "已修复", "time": "2026-10-01T09:30:00Z",
342				}
343				retEv := ev[2].(map[string]any)
344				retEv["seq"] = 5
345				m["events"] = []any{ev[0], ev[1], closeEv, retEv}
346			}},
347			{"领用编号重复", func(m map[string]any) {
348				m["parts"] = append(m["parts"].([]any), map[string]any{
349					"id": "P0001", "ticket_id": "T0001", "asset_id": "EQ-1",
350					"part_id": "ROLLER-02", "quantity": 1, "note": "搓纸轮", "returned": 0,
351				})
352			}},
353			{"下一领用序号不大于已用序号", func(m map[string]any) {
354				m["next_part_seq"] = 1
355			}},
356		}
357		for _, tc := range cases {
358			t.Run(tc.name, func(t *testing.T) {
359				dir, raw := write(t, tc.mutate)
360				if _, err := openStore(dir); err == nil {
361					t.Fatal("矛盾台账应拒绝加载")
362				}
363				if got := readFileBytes(t, dir); string(got) != string(raw) {
364					t.Fatal("拒绝加载不应改动原文件字节")
365				}
366			})
367		}
368	
369		// 基准台账本身合法，可正常加载。
370		dir, _ := write(t, func(m map[string]any) {})
371		s, err := openStore(dir)
372		if err != nil {
373			t.Fatalf("合法台账应能加载: %v", err)
374		}
375		if p := s.findPart("P0001"); p == nil || p.Returned != 1 {
376			t.Fatalf("合法台账的领用记录应加载，得到 %+v", p)
377		}
378	}
