380	// 无备件记录的有效旧库直接使用：缺省视为没有领用记录，领用编号从 P0001 开始。
381	func TestLegacyStoreWithoutParts(t *testing.T) {
382		dir := t.TempDir()
383		writeLedger(t, dir, nil) // 旧格式台账，无 parts 与 next_part_seq 字段
384		s, err := openStore(dir)
