	}
	if err := s.save(); err != nil {
		return err
	}
	fmt.Fprintf(w, "附件 %s 已撤销。\n", a.ID)
	fmt.Fprintf(w, "工单编号: %s\n", a.TicketID)
	fmt.Fprintf(w, "路径: %s\n", a.Path)
	return nil
}

